from pathlib import Path
out=Path('public/images');out.mkdir(exist_ok=True,parents=True)
base='''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 1000" role="img" aria-label="Atmospheric Sonora story artwork"><defs><linearGradient id="sky" x2=".4" y2="1"><stop stop-color="{top}"/><stop offset=".6" stop-color="{middle}"/><stop offset="1" stop-color="{bottom}"/></linearGradient><linearGradient id="shadow" x2="0" y2="1"><stop stop-color="#111717" stop-opacity="0"/><stop offset="1" stop-color="#111717" stop-opacity=".65"/></linearGradient><radialGradient id="glow"><stop stop-color="{light}" stop-opacity=".75"/><stop offset=".27" stop-color="{light}" stop-opacity=".30"/><stop offset="1" stop-color="{light}" stop-opacity="0"/></radialGradient><filter id="grain" x="0" y="0" width="100%" height="100%"><feTurbulence type="fractalNoise" baseFrequency=".42" numOctaves="3" seed="7" result="noise"/><feColorMatrix in="noise" type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".12"/></feComponentTransfer><feBlend in="SourceGraphic" mode="soft-light"/></filter><filter id="blur"><feGaussianBlur stdDeviation="12"/></filter></defs><rect width="800" height="1000" fill="url(#sky)"/>{art}<rect width="800" height="1000" fill="url(#shadow)"/><rect width="800" height="1000" filter="url(#grain)" opacity=".3" fill="#ac8b74"/></svg>'''
def save(name,top,middle,bottom,light,art):
    (out/(name+'.svg')).write_text(base.format(top=top,middle=middle,bottom=bottom,light=light,art=art))
